-- Khetha Path — complete local/demo database
-- Import this ONE file in phpMyAdmin > SQL. It creates the database and all tables.
-- The app uses MySQL/MariaDB locally (XAMPP) and can use the same schema in production.

CREATE DATABASE IF NOT EXISTS khetha_path
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE khetha_path;

CREATE TABLE IF NOT EXISTS users (
    userID INT UNSIGNED NOT NULL AUTO_INCREMENT,
    firstName VARCHAR(100) NOT NULL,
    lastName VARCHAR(100) NOT NULL DEFAULT '',
    email VARCHAR(190) NOT NULL,
    passwordHash VARCHAR(255) NOT NULL,
    phoneNumber VARCHAR(40) NULL,
    grade VARCHAR(30) NULL,
    interests JSON NULL,
    consentAt DATETIME NULL,
    createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (userID),
    UNIQUE KEY uq_users_email (email),
    KEY idx_users_grade (grade)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS careers (
    careerID VARCHAR(120) NOT NULL, title VARCHAR(190) NOT NULL, fieldName VARCHAR(120) NOT NULL, data JSON NOT NULL,
    PRIMARY KEY (careerID), KEY idx_careers_field (fieldName)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS qualifications (
    qualificationID VARCHAR(120) NOT NULL, title VARCHAR(190) NOT NULL, fieldName VARCHAR(120) NOT NULL, data JSON NOT NULL,
    PRIMARY KEY (qualificationID), KEY idx_qualifications_field (fieldName)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS providers (
    providerID VARCHAR(120) NOT NULL, name VARCHAR(190) NOT NULL, providerType VARCHAR(60) NOT NULL, data JSON NOT NULL,
    PRIMARY KEY (providerID), KEY idx_providers_type (providerType)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS learner_profiles (
    userID INT UNSIGNED NOT NULL,
    profileData JSON NOT NULL,
    createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (userID),
    CONSTRAINT fk_profile_user FOREIGN KEY (userID) REFERENCES users(userID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS assessmentResults (
    assessmentID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    userID INT UNSIGNED NOT NULL,
    source VARCHAR(50) NOT NULL,
    payload JSON NULL,
    derived JSON NULL,
    createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (assessmentID),
    KEY idx_assessment_user_source (userID, source, assessmentID),
    CONSTRAINT fk_assessment_user FOREIGN KEY (userID) REFERENCES users(userID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS favourites (
    favouriteID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    userID INT UNSIGNED NOT NULL,
    itemType VARCHAR(40) NOT NULL,
    itemID VARCHAR(120) NOT NULL,
    label VARCHAR(190) NOT NULL DEFAULT '',
    metadata JSON NULL,
    createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (favouriteID),
    UNIQUE KEY uq_favourite (userID, itemType, itemID),
    KEY idx_favourite_user (userID, createdAt),
    CONSTRAINT fk_favourite_user FOREIGN KEY (userID) REFERENCES users(userID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notifications (
    notificationID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    userID INT UNSIGNED NOT NULL,
    title VARCHAR(180) NOT NULL,
    message TEXT NOT NULL,
    type VARCHAR(40) NOT NULL DEFAULT 'journey',
    actionURL VARCHAR(255) NULL,
    scheduledAt DATETIME NULL,
    readAt DATETIME NULL,
    createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (notificationID),
    KEY idx_notifications_user (userID, readAt, scheduledAt, createdAt),
    CONSTRAINT fk_notification_user FOREIGN KEY (userID) REFERENCES users(userID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS notification_preferences (
    userID INT UNSIGNED NOT NULL,
    pushEnabled TINYINT(1) NOT NULL DEFAULT 0,
    deadlineReminders TINYINT(1) NOT NULL DEFAULT 1,
    assessmentReminders TINYINT(1) NOT NULL DEFAULT 1,
    journeyTips TINYINT(1) NOT NULL DEFAULT 1,
    updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (userID),
    CONSTRAINT fk_notification_pref_user FOREIGN KEY (userID) REFERENCES users(userID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS advisor_requests (
    requestID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    userID INT UNSIGNED NOT NULL,
    topic VARCHAR(60) NOT NULL,
    note TEXT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'submitted',
    createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (requestID),
    KEY idx_advisor_user (userID, createdAt),
    CONSTRAINT fk_advisor_user FOREIGN KEY (userID) REFERENCES users(userID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS content_sources (
    sourceID INT UNSIGNED NOT NULL AUTO_INCREMENT,
    sourceName VARCHAR(180) NOT NULL,
    sourceURL VARCHAR(500) NULL,
    sourceType VARCHAR(60) NOT NULL DEFAULT 'reference',
    versionLabel VARCHAR(80) NULL,
    approved TINYINT(1) NOT NULL DEFAULT 0,
    lastVerified DATE NULL,
    notes TEXT NULL,
    PRIMARY KEY (sourceID)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS learner_content_interactions (
    interactionID BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    userID INT UNSIGNED NOT NULL,
    eventType VARCHAR(80) NOT NULL,
    eventData JSON NULL,
    createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (interactionID),
    KEY idx_interaction_user (userID, createdAt),
    CONSTRAINT fk_interaction_user FOREIGN KEY (userID) REFERENCES users(userID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS learner_cv_edits (
    userID INT UNSIGNED NOT NULL,
    edits JSON NOT NULL,
    updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (userID),
    CONSTRAINT fk_cv_edits_user FOREIGN KEY (userID) REFERENCES users(userID) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

