INSERT INTO careers (careerID,title,fieldName,data) VALUES ('graphic_design','Graphic Design','Creative Arts & Design','{"id":"graphic_design","ofo_code":null,"title":"Graphic Design","alt_titles":["Graphic Designer","Visual Designer"],"field":"Creative Arts & Design","description":"Creates visual content — branding, layouts, digital and print media — for businesses and campaigns.","video_url":null,"riasec":{"R":10,"I":20,"A":100,"S":10,"E":40,"C":20},"work_values":{"achievement":65,"independence":75,"recognition":55,"relationships":35,"support":35,"working_conditions":55},"work_context":{"outdoors":0,"physical":5,"shifts":15,"travel":10,"people":35,"data":45,"things":40,"risk":5},"aptitudes":{"verbal":45,"numerical":35,"spatial":85,"form_perception":85,"clerical_perception":40,"motor_coordination":45,"finger_dexterity":50,"manual_dexterity":30},"math_track":"either","min_aps":null,"tags":[],"qualification_ids":["dip_graphic_design"],"demand":"medium","salary_band":"R150k – R400k/yr","subject_requirements":[{"subject":"Visual Arts","min_percent":50,"necessity":"required"},{"subject":"Information Technology","min_percent":null,"necessity":"recommended"},{"subject":"Engineering Graphics & Design","min_percent":null,"necessity":"recommended"}],"pathways":["TVET/private college Higher Certificate in Graphic Design, articulating into a Diploma","Short courses + a design portfolio route into a Diploma programme"],"riasec_code":"AEI"}' ) ON DUPLICATE KEY UPDATE title=VALUES(title),fieldName=VALUES(fieldName),data=VALUES(data);
INSERT INTO careers (careerID,title,fieldName,data) VALUES ('electrician','Electrician (Artisan Trade)','Technical Trades','{"id":"electrician","ofo_code":null,"title":"Electrician (Artisan Trade)","alt_titles":["Electrician"],"field":"Technical Trades","description":"Installs, maintains and repairs electrical wiring and systems in homes, businesses and industry, as a qualified artisan.","video_url":null,"riasec":{"R":100,"I":50,"A":10,"S":10,"E":20,"C":40},"work_values":{"achievement":65,"independence":65,"recognition":40,"relationships":35,"support":40,"working_conditions":30},"work_context":{"outdoors":55,"physical":75,"shifts":40,"travel":45,"people":30,"data":20,"things":95,"risk":75},"aptitudes":{"verbal":35,"numerical":55,"spatial":65,"form_perception":60,"clerical_perception":40,"motor_coordination":80,"finger_dexterity":75,"manual_dexterity":80},"math_track":"either","min_aps":null,"tags":["trade","high_demand"],"qualification_ids":["electrician_trade"],"demand":"high","salary_band":"R150k – R350k/yr","subject_requirements":[{"subject":"Technical Sciences","min_percent":50,"necessity":"required"},{"subject":"Technical Mathematics","min_percent":null,"necessity":"recommended"},{"subject":"Engineering Graphics & Design","min_percent":null,"necessity":"recommended"}],"pathways":["TVET N-courses (N1–N6) in Electrical Engineering, then an apprenticeship and trade test","Direct workplace apprenticeship with block release to a TVET college"],"riasec_code":"RIC"}' ) ON DUPLICATE KEY UPDATE title=VALUES(title),fieldName=VALUES(fieldName),data=VALUES(data);
INSERT INTO careers (careerID,title,fieldName,data) VALUES ('agricultural_science','Agricultural Sciences (BSc Agric)','Agriculture','{"id":"agricultural_science","ofo_code":null,"title":"Agricultural Sciences (BSc Agric)","alt_titles":["Agricultural Scientist","Agronomist"],"field":"Agriculture","description":"Applies science to farming and food production — soil, crops, livestock and sustainable land use.","video_url":null,"riasec":{"R":80,"I":90,"A":10,"S":20,"E":30,"C":30},"work_values":{"achievement":70,"independence":65,"recognition":45,"relationships":40,"support":45,"working_conditions":30},"work_context":{"outdoors":85,"physical":60,"shifts":25,"travel":40,"people":35,"data":55,"things":60,"risk":35},"aptitudes":{"verbal":50,"numerical":65,"spatial":45,"form_perception":50,"clerical_perception":45,"motor_coordination":50,"finger_dexterity":40,"manual_dexterity":45},"math_track":"mathematics","min_aps":28,"tags":["green"],"qualification_ids":["bsc_agric"],"demand":"medium","salary_band":"R180k – R450k/yr","subject_requirements":[{"subject":"Agricultural Sciences","min_percent":55,"necessity":"required"},{"subject":"Mathematics","min_percent":50,"necessity":"required"},{"subject":"Life Sciences","min_percent":null,"necessity":"recommended"},{"subject":"Physical Sciences","min_percent":null,"necessity":"recommended"}],"pathways":["National Diploma in Agriculture via a university of technology","Higher Certificate in Agricultural Management, articulating into a Diploma"],"riasec_code":"IRE"}' ) ON DUPLICATE KEY UPDATE title=VALUES(title),fieldName=VALUES(fieldName),data=VALUES(data);
