INSERT INTO content_sources (sourceName, sourceURL, sourceType, versionLabel, approved, lastVerified, notes)
SELECT 'National Career Advice Portal (NCAP)', 'https://ncap.careerhelp.org.za/', 'government-reference', 'reference', 1, CURDATE(), 'Reference source for Khetha Path information architecture. Production data should be synchronised through an approved DHET/NCAP integration.'
WHERE NOT EXISTS (SELECT 1 FROM content_sources WHERE sourceName = 'National Career Advice Portal (NCAP)');

INSERT INTO content_sources (sourceName, sourceURL, sourceType, versionLabel, approved, lastVerified, notes)
SELECT 'DHET Career Development Services / Khetha', 'https://ncap.careerhelp.org.za/', 'government-reference', 'reference', 1, CURDATE(), 'Government programme reference. Keep production content traceable to approved sources.'
WHERE NOT EXISTS (SELECT 1 FROM content_sources WHERE sourceName = 'DHET Career Development Services / Khetha');
